SELECT CASE WHEN amount >= 3600 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, account_id, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, MIN(txn_time) AS first_seen, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min FROM transactions GROUP BY CASE WHEN amount >= 3600 THEN 'HIGH' ELSE 'LOW' END, account_id HAVING span_minutes > 0 ORDER BY amount_tier NULLS LAST
